export const SWITCH_THUMB_SIZE = 18;
export const SWITCH_TRACK_WIDTH = 40;
export const SWITCH_THUMB_STRETCH = 6;
export const SWITCH_TRACK_HEIGHT = 23.5;
export const SWITCH_STRETCH_DURATION = "0.22s";
export const SWITCH_TRANSITION_DURATION = "0.3s";
export const SWITCH_SPRING_EASING = "cubic-bezier(0.34, 1.45, 0.64, 1)";
export const SWITCH_THUMB_GAP = (SWITCH_TRACK_HEIGHT - SWITCH_THUMB_SIZE) / 2;

export const SWITCH_THUMB_CHECKED_OFFSET =
  SWITCH_TRACK_WIDTH - SWITCH_THUMB_SIZE - SWITCH_THUMB_GAP;

export const SWITCH_THUMB_TRAVEL =
  SWITCH_THUMB_CHECKED_OFFSET - SWITCH_THUMB_GAP;
